def the_readback(case, data):
    """THE TABLE — the readback's forms on file, no new form: the rows one per verse, graded; the pointer row with its referent ahead; the state row; the two open rows; the twin diffed; the verses no one cites; no retrograde row"""
    del P_[:]
    ask = case['ask']
    rb_ = data['the_readback']['value']
    if ask == 'the_table':
        ink('15:1-23', 'the rows %d, one per verse %s; the grades %s' % (len(rb_), [r['verses'] for r in rb_] == ['Deut 15:%d' % v for v in range(1, 24)], dict(collections.Counter(r['grade'] for r in rb_))))
        move('THE LOOP.md step 6 (the forms on file — chapter 5\'s laws\' readback the form); every reference row\'s entry found on the tape by kind and first verse; every row\'s kin cell by CALL', 'THE READBACK ON THIS CHAPTER — law from its first word to its last with ONE narrative verb (15:15 a REFERENCE row on the tape\'s close, never a second act): T4 rows graded against the cells that compile their kin by CALL (twenty-three — every row has kin), T1 reference rows against the tape\'s lines by kind and first verse; the state row, the pointer row, the two open rows inside')
        dat('the table a DATA row (the_readback — the rows, the holes, the open rows); the exam\'s person the scholar who reads the table — accepted')
